CREATE TABLE public.finance_tax_notices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),reference text NOT NULL DEFAULT '',tax_year text NOT NULL DEFAULT '',due_date date NOT NULL,amount numeric NOT NULL CHECK(amount>0 AND amount=round(amount,2)),source_document text,created_by uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.finance_tax_notices TO authenticated; GRANT ALL ON public.finance_tax_notices TO service_role;
ALTER TABLE public.finance_tax_notices ENABLE ROW LEVEL SECURITY;
CREATE POLICY tax_notice_read ON public.finance_tax_notices FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id));
CREATE OR REPLACE FUNCTION public.finance_tax_notice_save(t uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ident uuid; BEGIN IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;IF nullif(btrim(p->>'reference'),'') IS NULL OR (p->>'amount')::numeric<=0 OR (p->>'amount')::numeric<>round((p->>'amount')::numeric,2) OR nullif(p->>'due_date','') IS NULL THEN RAISE EXCEPTION 'Confirm reference, due date and amount';END IF;INSERT INTO finance_tax_notices(tenant_id,reference,tax_year,due_date,amount,source_document,created_by) VALUES(t,p->>'reference',coalesce(p->>'tax_year',''),(p->>'due_date')::date,(p->>'amount')::numeric,nullif(p->>'source_document',''),auth.uid()) RETURNING id INTO ident;INSERT INTO audit_log(tenant_id,user_id,action,entity_type,entity_id) VALUES(t,auth.uid(),'tax_notice_recorded','finance_tax_notices',ident::text);RETURN ident;END $$;
REVOKE ALL ON FUNCTION public.finance_tax_notice_save(uuid,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_tax_notice_save(uuid,jsonb) TO authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.post_expense_bill(uuid)'::regprocedure) INTO def;IF position('v_enforce_sod boolean;' IN def)=0 OR position('SELECT id INTO v_ap_account' IN def)=0 THEN RAISE EXCEPTION 'Bill approval anchors unavailable';END IF;def:=replace(def,'v_enforce_sod boolean;','v_enforce_sod boolean; asset_line record;');def:=replace(def,'SELECT id INTO v_ap_account','PERFORM public.finance_assert_open(v_tenant,v_bill.bill_date); FOR asset_line IN SELECT * FROM public.expense_bill_allocations WHERE bill_id=p_bill_id AND tenant_id=v_tenant AND capitalize FOR UPDATE LOOP IF NOT public.finance_schedule_manager(v_tenant) OR asset_line.amount<=coalesce((SELECT capitalisation_limit FROM public.finance_schedule_settings WHERE tenant_id=v_tenant),5000) OR asset_line.useful_life_months IS NULL OR asset_line.useful_life_months<=0 OR nullif(btrim(asset_line.asset_name),'''') IS NULL THEN RAISE EXCEPTION ''Owner-confirmed asset above capitalisation limit required'';END IF;PERFORM public.capitalize_bill_allocation(asset_line.id);END LOOP; SELECT id INTO v_ap_account');EXECUTE def;END $$;